<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import {fashionRequest} from '@/api/fashion/client'
import type {RuoYiResult} from '@/api/fashion/types'
import {createPool,getPool,getPoolOptions,getPoolPage,getPoolSelection,savePoolSelection} from '@/api/fashion/pool'
import {isSelected,toggleSelected,priceRange,filterRangeError,groupRangeError,type PoolSnapshot,type PoolSelection,type PoolOptions,type PoolCombination,type PoolPage,type PoolHistory} from '@/api/fashion/poolTypes'
import type {ProductAttributeField} from '@/api/fashion/types'
import {blankConditionDraft,activeConditionGroups,conditionRequest,restoreConditionDraft,changeConditionMode,copyConditionGroup,resetConditionGroup} from './conditionState'
import {savedSelection,draftCacheValue,readDraftCache} from './workspaceState'
import useUserStore from '@/store/modules/user'
import auth from '@/plugins/auth'
import FilterGroup from './FilterGroup.vue'
import TotalConditions from './TotalConditions.vue'
import DeliveryTools from './DeliveryTools.vue'
import ProductThumbnail from '../components/ProductThumbnail.vue'
const router=useRouter(),route=useRoute(),step=ref(0),busy=ref(false),loading=ref(false),error=ref(''),dirty=ref(false)
const form=reactive(blankConditionDraft()),attributeFields=ref<ProductAttributeField[]>([]),copyVisible=ref(false),copySource=ref(0),copyTarget=ref(1)
