const selection=ref<PoolSelection>(emptySelection()),page=ref<PoolPage>({items:[],total:0,page:1,pageSize:20,rawCount:0})
const query=reactive({page:1,pageSize:20,sort:'identity',keyword:''}),selectedCount=computed(()=>selection.value.all?Math.max(0,(pool.value?.total??0)-selection.value.excludedIds.length):selection.value.selectedIds.length)
const details=ref<PoolCombination>(),detailsVisible=ref(false),historyVisible=ref(false),historyLoading=ref(false),historyError=ref(''),history=ref<PoolHistory[]>([]),toolVisible=ref(false),toolKind=ref<'image'|'ppt'>('image')
const taskSummary=ref<{combinationId:string;status:string;stale?:boolean}[]>([]),taskSummaryError=ref(''),taskSummaryLoaded=ref(false)
const compareItems=ref<PoolCombination[]>([]),compareVisible=ref(false)
function addCompare(row:PoolCombination){if(compareItems.value.some(x=>x.id===row.id))return ElMessage.info('已在对比列表');if(compareItems.value.length>=4)return ElMessage.warning('最多对比四套，请先移除一套');compareItems.value.push(row)}
let controller:AbortController|undefined,sequence=0,contextSequence=0,selectionRevision=0,formRevision=0,cacheReady=false
const cacheKey=`fashion:unsubmitted-conditions:${String(useUserStore().id)}`
function persistDraft(){if(!cacheReady||step.value!==0)return;try{sessionStorage.setItem(cacheKey,draftCacheValue(form,pool.value?.id))}catch{/* 浏览器禁用存储时仍可操作当前表单。 */}}
function clearResults(){controller?.abort();++sequence;page.value={items:[],total:0,page:1,pageSize:query.pageSize,rawCount:0};loading.value=false;details.value=undefined;detailsVisible.value=false;compareItems.value=[];compareVisible.value=false;toolVisible.value=false}
function markDirty(){selectionRevision++;dirty.value=true}
async function run(fn:()=>Promise<void>,token=contextSequence){error.value='';try{await fn();return token===contextSequence}catch(e){if(token===contextSequence)error.value=e instanceof Error?e.message:'操作失败，请重试';return false}}
async function loadPage(){if(!pool.value)return false;const id=pool.value.id,currentStep=step.value,seq=++sequence;controller?.abort();controller=new AbortController();loading.value=true;try{const result=await getPoolPage(id,{...query,selectedOnly:currentStep===2},controller.signal);if(seq===sequence&&pool.value?.id===id&&step.value===currentStep){page.value=result.data;return true}return false}catch(e){if(seq===sequence)error.value=e instanceof Error?e.message:'读取失败';return false}finally{if(seq===sequence)loading.value=false}}
async function search(){query.page=1;await loadPage()}
async function save(){if(legacyReadOnly.value)return false;if(!pool.value||!dirty.value)return true;const id=pool.value.id,token=contextSequence,issuedRevision=selectionRevision,body=JSON.parse(JSON.stringify(selection.value));busy.value=true;try{const response=(await savePoolSelection(id,body)).data;if(token!==contextSequence||pool.value?.id!==id)return false;const applied=savedSelection(selection.value,response,issuedRevision,selectionRevision);selection.value=applied.selection;dirty.value=applied.dirty;ElMessage.success(applied.dirty?'先前选择已保存，后续修改仍待保存':'选择已保存');return !applied.dirty}catch(e){if(token===contextSequence)error.value=e instanceof Error?e.message:'保存失败';return false}finally{if(token===contextSequence)busy.value=false}}
async function leaveDirty(){if(!dirty.value)return true;try{await ElMessageBox.confirm('当前选择尚未保存，是否先保存？','保存选择',{confirmButtonText:'保存并继续',cancelButtonText:'留在当前页面',type:'warning'});return await save()}catch{return false}}
async function generate(){if(!form.title.trim())return ElMessage.warning('请填写选品工作单名称');const groups=activeConditionGroups(form);if(groups.some(g=>!g.categoryLeafCodes.length))return ElMessage.warning('每个活动筛选组至少选择一个三级分类');const invalidGroup=groups.find(g=>groupRangeError(g));if(invalidGroup)return ElMessage.warning(`请修正“${invalidGroup.label}”的条件：${groupRangeError(invalidGroup)}`);const totalError=filterRangeError(form.totalMin,form.totalMax,'整套价格');if(totalError)return ElMessage.warning(totalError);const request=conditionRequest(form),token=++contextSequence;if(!await leaveDirty()||token!==contextSequence)return;persistDraft();clearResults();busy.value=true;try{await run(async()=>{const created=(await createPool(request)).data;if(token!==contextSequence)return;const draft=(await getPoolSelection(created.id)).data;if(token!==contextSequence)return;pool.value=created;selection.value=draft;selectionRevision++;dirty.value=false;localDraftRestored.value=false;try{sessionStorage.removeItem(cacheKey)}catch{}step.value=1;query.page=1;query.keyword='';query.sort='identity';await router.replace({query:{...route.query,poolId:created.id}});if(token===contextSequence)await loadPage()},token)}finally{if(token===contextSequence)busy.value=false}}
async function go(next:number){const token=contextSequence;if(next===2&&dirty.value&&!await save())return;if(token!==contextSequence)return;step.value=next;query.page=1;query.keyword='';query.sort='identity';if(next>0)await loadPage();else persistDraft()}
function toggle(id:string,value:boolean){if(legacyReadOnly.value)return;toggleSelected(selection.value,id,value);markDirty()}
function selectPage(){page.value.items.forEach(x=>toggle(x.id,true))}
async function selectAll(){if(legacyReadOnly.value)return;const token=contextSequence;try{await ElMessageBox.confirm(`选入本方案池全部 ${pool.value?.total} 套，可跨页排除个别方案。`,'选择全部',{type:'info'});if(token!==contextSequence)return;selection.value.all=true;selection.value.selectedIds=[];selection.value.excludedIds=[];markDirty()}catch{}}
function clearSelection(){if(legacyReadOnly.value)return;selection.value.all=false;selection.value.selectedIds=[];selection.value.excludedIds=[];markDirty()}
function rename(id:string,name:string){if(legacyReadOnly.value)return;selection.value.names[id]=name;markDirty()}
async function moveFirst(id:string){if(legacyReadOnly.value)return;const token=contextSequence;selection.value.orderedIds=[id,...selection.value.orderedIds.filter(x=>x!==id)];markDirty();if(await save()&&token===contextSequence)await loadPage()}
function chooseVariant(id:string,key:string,productId:string){if(legacyReadOnly.value)return;selection.value.variantSelections[id]={...selection.value.variantSelections[id],[key]:productId};markDirty()}
async function openExisting(id:string){let appliedRevision:number|undefined;const token=++contextSequence;if(!await leaveDirty()||token!==contextSequence)return;persistDraft();clearResults();busy.value=true;try{const success=await run(async()=>{const [p,s]=await Promise.all([getPool(id),getPoolSelection(id)]);if(token!==contextSequence)return;pool.value=p.data;selection.value=s.data;selectionRevision++;if(p.data.request)Object.assign(form,restoreConditionDraft(p.data.request));appliedRevision=formRevision;dirty.value=false;localDraftRestored.value=false;historyVisible.value=false;step.value=1;query.page=1;query.keyword='';query.sort='identity';await router.replace({query:{...route.query,poolId:id}});if(token===contextSequence)await loadPage()},token);return success?appliedRevision:undefined}finally{if(token===contextSequence)busy.value=false}}
let historySequence=0,historyController:AbortController|undefined,summarySequence=0,summaryController:AbortController|undefined
async function loadHistory(){const issued=++historySequence;historyController?.abort();historyController=new AbortController();historyLoading.value=true;historyError.value='';history.value=[];try{const response=await fashionRequest<RuoYiResult<PoolHistory[]>>({path:'pools',signal:historyController.signal});if(issued===historySequence)history.value=response.data}catch(e){if(issued===historySequence)historyError.value=e instanceof Error?e.message:'工作单读取失败'}finally{if(issued===historySequence)historyLoading.value=false}}
function budgetSummary(row:PoolHistory){return (row.priceBasis==='vip'?'VIP':'团购')+' '+(row.budgetMin==null?'不限':row.budgetMin)+' ～ '+(row.budgetMax==null?'不限':row.budgetMax)}
function variantSummary(row:PoolCombination){return row.items.map(item=>{const id=selection.value.variantSelections[row.id]?.[item.key];const variant=item.variants.find(v=>v.productId===id);return item.name+'：'+(variant?variant.colorName+' / '+variant.sizeCode+' / '+variant.skuCode:'尚未指定规格')}).join('；')}
function tryOnSummary(row:PoolCombination){if(!auth.hasPermi('fashion:quote:query'))return'无试衣状态查看权限';if(dirty.value)return'选择或规格待保存，试衣状态待核对';if(taskSummaryError.value)return'状态暂不可读';if(!taskSummaryLoaded.value)return'尚未读取';const tasks=taskSummary.value.filter(t=>t.combinationId===row.id);if(!tasks.length)return'尚无试衣任务';return tasks.map(t=>t.stale?'素材已变化':({queued:'排队中',running:'处理中',review:'待复核',adopted:'已采用',rejected:'未采用',failed:'失败',unknown:'状态待确认',cancelled:'已取消',cancel_requested:'取消请求中'} as Record<string,string>)[t.status]||t.status).join(' / ')}
function proposalSummary(row:PoolCombination){const problems:string[]=[];if(dirty.value)problems.push('选择待保存');if(row.items.some(i=>i.groupPriceMin==null&&i.vipPriceMin==null))problems.push('业务价格有缺项');if(row.items.some(i=>!i.mainImageUrl))problems.push('商品主图有缺项');return problems.length?problems.join('；'):'需在提案工具核对许可与导出范围'}
async function refreshTaskSummary(){if(!pool.value)return;const id=pool.value.id,version=selection.value.rowVersion,issued=++summarySequence;summaryController?.abort();summaryController=new AbortController();taskSummaryLoaded.value=false;taskSummaryError.value='';try{const response=await fashionRequest<RuoYiResult<{tasks:typeof taskSummary.value}>>({path:'pools/'+id+'/proposal/images',params:{rowVersion:version},signal:summaryController.signal});if(issued!==summarySequence||pool.value?.id!==id||selection.value.rowVersion!==version||step.value!==2)return;if(!Array.isArray(response.data.tasks))throw new Error('任务摘要格式不符合业务接口');taskSummary.value=response.data.tasks;taskSummaryLoaded.value=true}catch(e){if(issued===summarySequence&&pool.value?.id===id&&step.value===2)taskSummaryError.value=e instanceof Error?e.message:'任务摘要读取失败'}}
watch([()=>pool.value?.id,step,()=>selection.value.rowVersion,toolVisible],()=>{++summarySequence;summaryController?.abort();taskSummary.value=[];taskSummaryLoaded.value=false;taskSummaryError.value='';if(step.value===2&&pool.value&&!toolVisible.value&&auth.hasPermi('fashion:quote:query'))void refreshTaskSummary()})
async function fresh(){const token=++contextSequence;if(!await leaveDirty()||token!==contextSequence)return;clearResults();busy.value=false;pool.value=undefined;selection.value=emptySelection();selectionRevision++;dirty.value=false;step.value=0;localDraftRestored.value=false;Object.assign(form,blankConditionDraft(options.value.defaultWarehouseCode),{totalMin:undefined,totalMax:undefined});try{sessionStorage.removeItem(cacheKey)}catch{}await router.replace({query:{}})}
async function openTool(kind:'image'|'ppt'){if(legacyReadOnly.value||dirty.value&&!await save())return;const token=contextSequence,revision=selectionRevision;if(!await loadPage()||token!==contextSequence||revision!==selectionRevision)return;toolKind.value=kind;toolVisible.value=true}
function beforeUnload(e:BeforeUnloadEvent){persistDraft();if(dirty.value){e.preventDefault();e.returnValue=''}}
watch(form,()=>{formRevision++;persistDraft()},{deep:true,flush:'sync'})
onBeforeRouteLeave(async()=>{persistDraft();return await leaveDirty()})
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);const token=contextSequence;busy.value=true;let cached:ReturnType<typeof readDraftCache>;try{cached=readDraftCache(sessionStorage.getItem(cacheKey))}catch{}try{options.value=(await getPoolOptions()).data;if(token!==contextSequence)return;attributeFields.value=options.value.attributeFields??[];if(typeof route.query.poolId==='string'){const id=route.query.poolId,expectedContext=contextSequence+1,restoredRevision=await openExisting(id);if(contextSequence===expectedContext&&pool.value?.id===id&&restoredRevision!==undefined&&formRevision===restoredRevision&&cached&&cached.poolId===id){Object.assign(form,cached.form);localDraftRestored.value=true}} else if(cached?.poolId===null){Object.assign(form,cached.form);localDraftRestored.value=true}else form.totalConditions.warehouseCode=options.value.defaultWarehouseCode??''}catch(e){if(token===contextSequence)error.value=e instanceof Error?e.message:'加载失败'}finally{cacheReady=true;if(token===contextSequence)busy.value=false}})
onBeforeUnmount(()=>{contextSequence++;++historySequence;++summarySequence;controller?.abort();historyController?.abort();summaryController?.abort();window.removeEventListener('beforeunload',beforeUnload)})
</script>
<style scoped>
.compare-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:16px}.pool-workspace{max-width:1800px;margin:auto}.page-header,.actions,.steps,.section-title,.table-toolbar,.stats,.workspace-meta{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.page-header{justify-content:space-between}.page-header h2{margin:0}.page-header p,.hint{color:var(--el-text-color-secondary);font-size:13px}.steps{padding:16px 0;border-bottom:1px solid var(--el-border-color)}.steps .el-button{margin:0;min-width:160px}.workspace-meta{margin:20px 0}.workspace-meta>.el-input{max-width:360px}.section-title h3{margin-right:8px}.section-title span{flex:1;font-size:13px;color:var(--el-text-color-secondary)}.summary-bar{padding:18px 18px 0;background:var(--el-fill-color-light);border-radius:8px}.separator{padding:0 8px}.stats{padding:16px;background:var(--el-color-primary-light-9);border-radius:6px;margin-bottom:16px;gap:32px}.stats strong{font-size:20px;color:var(--el-color-primary)}.table-toolbar{margin-bottom:12px}.product-cell{display:flex;gap:10px;align-items:center}.product-cell :deep(.thumbnail),.no-image{width:68px;height:80px;flex-shrink:0}.no-image{display:grid;place-items:center;background:var(--el-fill-color-light);color:var(--el-text-color-secondary);font-size:12px}.product-cell p{margin:6px 0;font-size:12px;overflow-wrap:anywhere}.pagination{margin-top:16px;justify-content:flex-end;max-width:100%;overflow-x:auto}.space{margin:16px 0}
</style>
